fn check_npc_asset_folder(folder: &str) {
    let path = root().join(folder);
    let f: Value =
        serde_json::from_slice(&std::fs::read(path.join("oracle.json")).unwrap()).unwrap();
    let ids: Vec<u32> = serde_json::from_value(f["body_types"].clone()).unwrap();
    for c in f["bas"].as_array().unwrap() {
        let b = rs09_client::npc::Bas::decode(
            &std::fs::read(path.join(c["file"].as_str().unwrap())).unwrap(),
        )
        .unwrap();
        let m = &b.movement;
        assert_eq!(
            serde_json::json!([
                m.idle,
                m.walk,
                m.run,
                m.stand[0],
                m.stand[1],
                m.turns[0],
                m.turns[1],
                m.turns[2],
                b.terrain[0],
                b.terrain[1]
            ]),
            c["expected"]
        );
    }
    for (name, expected) in f["inputs"].as_object().unwrap() {
        assert_eq!(
            hash(&std::fs::read(path.join(name)).unwrap()),
            expected.as_str().unwrap()
        );
    }
    check_npc_bodies(f, |name| std::fs::read(path.join(name)).unwrap(), &ids);
}
fn check_npc_bodies(fixture: Value, input: impl Fn(&str) -> Vec<u8>, ids: &[u32]) {
    use rs09_client::{npc, shadow, surface, texture};
    use std::collections::BTreeMap;
    let materials = texture::materials(&input("materials.bin")).unwrap();
    let mut bodies = BTreeMap::new();
    for id in ids {
        let d = npc::Definition::decode(&input(&format!("npc_{id}.bin"))).unwrap();
        let bas = npc::Bas::decode(&input(&format!("bas_{}.bin", d.bas))).unwrap();
        let models = d
            .models
            .iter()
            .map(|id| {
                (
                    *id,
                    Model::decode(&input(&format!("model_{id}.bin"))).unwrap(),
                )
            })
            .collect();
        let mut model = d.assemble(&models).unwrap();
        model.surfaces = surface::prepare(&model, &materials);
        bodies.insert(format!("npc_{id}.bin"), (d, bas, model));
    }
    for c in fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|c| c["kind"].as_str().unwrap().starts_with("npc"))
    {
        let name = c["file"].as_str().unwrap();
        let (d, bas, model) = &bodies[name];
        let mut bytes = Vec::new();
        let ints = |out: &mut Vec<u8>, values: &[i32]| {
            for v in values {
                out.extend(v.to_be_bytes());
            }
        };
        match c["kind"].as_str().unwrap() {
            "npcdecode" => {
                ints(&mut bytes, &[d.name.len() as i32]);
                bytes.extend(d.name.as_bytes());
                ints(
                    &mut bytes,
                    &[
                        d.size,
                        d.bas,
                        d.resize[0],
                        d.resize[1],
                        d.lighting[0],
                        d.lighting[1],
                        d.turn_speed,
                        i32::from(d.rotates),
                        i32::from(d.shadow),
                        i32::from(d.shadow_colors[0]),
                        i32::from(d.shadow_colors[1]),
                        i32::from(d.shadow_alpha[0]),
                        i32::from(d.shadow_alpha[1]),
                    ],
                );
                ints(&mut bytes, &[d.models.len() as i32]);
                for id in &d.models {
                    ints(&mut bytes, &[*id as i32]);
                }
                for pairs in [&d.recolor, &d.retexture] {
                    ints(&mut bytes, &[pairs.len() as i32]);
                    for pair in pairs {
                        for v in pair {
                            bytes.extend(v.to_be_bytes());
                        }
                    }
                }
                ints(&mut bytes, &[d.offsets.len() as i32]);
                for (i, v) in &d.offsets {
                    ints(&mut bytes, &[*i as i32]);
                    ints(&mut bytes, v);
                }
                let b = &bas.movement;
                ints(
                    &mut bytes,
                    &[
                        b.idle,
                        b.walk,
                        b.run,
                        b.stand[0],
                        b.stand[1],
                        b.turns[0],
                        b.turns[1],
                        b.turns[2],
                        bas.terrain[0],
                        bas.terrain[1],
                    ],
                );
            }
            "npcmodel" => bytes = canonical(model),
            "npcpose" => {
                let seq = Sequence::decode(&input(c["seq"].as_str().unwrap())).unwrap();
                let base = Base::decode(
                    c["base_id"].as_u64().unwrap() as u16,
                    &input(c["base"].as_str().unwrap()),
                )
                .unwrap();
                let a = Frame::decode(&input(c["first"].as_str().unwrap()), &base).unwrap();
                let b = Frame::decode(&input(c["next"].as_str().unwrap()), &base).unwrap();
                let pose = d.pose(
                    model,
                    &seq,
                    &base,
                    &a,
                    c["tween"].as_bool().unwrap().then_some(&b),
                    (
                        c["delta"].as_i64().unwrap() as i32,
                        c["length"].as_i64().unwrap() as i32,
                    ),
                );
                for v in &pose.vertices {
                    ints(&mut bytes, v);
                }
                for (i, s) in pose.surfaces.iter().enumerate() {
                    if surface::visible(&pose, i, &materials) {
                        for n in s.normals {
                            ints(&mut bytes, &n);
                        }
                    }
                }
                for i in 0..pose.faces.len() {
                    if surface::visible(&pose, i, &materials) {
                        bytes.extend(pose.colors[i].to_be_bytes());
                        bytes.push(pose.alpha[i]);
                    }
                }
                let s = shadow::character_styled(
                    &pose,
                    [6976, 6464],
                    c["angle"].as_i64().unwrap() as i32,
                    seq.stretches,
                    Some((&base, &a)),
                    shadow::CharacterStyle {
                        size: d.size,
                        colors: d.shadow_colors,
                        alpha: d.shadow_alpha,
                    },
                );
                for v in &s.vertices {
                    ints(&mut bytes, v);
                }
                for i in 0..s.faces.len() {
                    bytes.extend(s.colors[i].to_be_bytes());
                    bytes.push(s.alpha[i]);
                }
            }
            _ => unreachable!(),
        }
        assert_eq!(
            hash(&bytes),
            c["expected"].as_str().unwrap(),
            "NPC {}",
            c["id"]
        );
    }
}

#[test]
fn floor_definitions_match_original_hsl_and_texture_settings() {
    use rs09_client::floor::{Overlay, Underlay};
    for c in fixture()["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|c| c["kind"] == "underlay" || c["kind"] == "overlay")
    {
        let name = c["file"].as_str().unwrap();
        let data = input(name);
        let values = if c["kind"] == "underlay" {
            let t = Underlay::decode(&data).unwrap();
            [
                t.weighted_hue,
                t.saturation,
                t.lightness,
                t.chroma,
                t.texture,
                t.scale,
            ]
        } else {
            let t = Overlay::decode(&data).unwrap();
            [
                t.color,
                t.texture,
                t.scale,
                i32::from(t.blend),
                t.water_color as i32,
                i32::from(t.water_opacity),
            ]
        };
        let bytes: Vec<u8> = values.iter().flat_map(|v| v.to_be_bytes()).collect();
        assert_eq!(hash(&bytes), c["expected"].as_str().unwrap(), "{name}");
    }
}

