#[test]
fn every_tile_shape_and_rotation_matches_rt4_jvm() {
    for c in fixture()["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|c| c["kind"] == "tile")
    {
        let mesh = rs09_client::tile_mesh::build(
            c["shape"].as_u64().unwrap() as usize,
            c["rotation"].as_u64().unwrap() as usize,
            [-16, -32, -96, -48],
        )
        .unwrap();
        let mut bytes = Vec::new();
        for vertex in mesh.vertices {
            for n in vertex {
                bytes.extend(n.to_be_bytes());
            }
        }
        for (overlay, face) in mesh.faces {
            bytes.push(u8::from(overlay));
            for n in face {
                bytes.extend((n as i32).to_be_bytes());
            }
        }
        assert_eq!(
            hash(&bytes),
            c["expected"].as_str().unwrap(),
            "tile {}",
            c["id"]
        );
    }
}

